async function pinnedBuilds() {
	const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
	const ids = new Set(windows.filter((client) => new URL(client.url).pathname.startsWith(BUILD.scope)).map((client) => client.id));
	const meta = await caches.open(META_CACHE);
	const pinned = new Set();
	const pages = await caches.open(PAGE_CACHE);
	for (const key of await pages.keys()) {
		const page = await pages.match(key);
		if (page && VERSION_PATTERN.test(page.headers.get(HTML_VERSION))) pinned.add(page.headers.get(HTML_VERSION));
	}
	const reported = new Set();
	for (const key of await meta.keys()) {
		if (!key.url.startsWith(`${META_ROOT}client/`)) continue;
		const id = decodeURIComponent(key.url.slice(`${META_ROOT}client/`.length));
		try {
			const entry = await (await meta.match(key)).json();
			// A reserved navigation client is absent from matchAll until its
			// document becomes execution-ready. Give that newly written pin time
			// to appear; closed tabs are reclaimed after the same short grace.
			if (!ids.has(id) && !(entry.pageURL && Date.now() - entry.savedAt < NAVIGATION_PIN_GRACE)) {
				await meta.delete(key); continue;
			}
			if (VERSION_PATTERN.test(entry.version)) {
				pinned.add(entry.version);
				reported.add(id);
			}
		} catch { /* Invalid metadata cannot pin an arbitrary cache. */ }
	}
	// A freshly navigating/frozen document may not have reported its build yet.
	// Defer eviction rather than guess which old lazy chunks that client needs.
	if ([...ids].some((id) => !reported.has(id))) {
		for (const build of await listBuilds()) pinned.add(build.version);
	}
	return pinned;
}

// Called under the shared metadata lock; no network transfer holds this lock.
async function pruneCaches(reserveBytes = 0, reservedVersion) {
	await pruneSharePages();
	const builds = await listBuilds();
	const pinned = await pinnedBuilds();
	pinned.add(BUILD.version);
	if (reservedVersion) pinned.add(reservedVersion);
	const now = Date.now();
	for (const build of builds) if (build.preparingUntil > now) pinned.add(build.version);
	// A throttled worker may still hold its preparation lock after its persisted
	// lease expires. Never evict files out from underneath that live operation.
	if (self.navigator?.locks?.query) {
		const prefix = `${PREFIX}prepare:`;
		const { held } = await self.navigator.locks.query();
		for (const lock of held) if (lock.name.startsWith(prefix) && VERSION_PATTERN.test(lock.name.slice(prefix.length))) pinned.add(lock.name.slice(prefix.length));
	}
	// An incomplete replacement does not discard the last complete build.
	// Older records without the flag were committed only after a full install.
	const newestComplete = builds.find((build) => build.complete !== false);
	const meta = await caches.open(META_CACHE);
	const sizes = new Map(builds.map((build) => [build.version, build.assets.reduce((total, asset) => total + asset.size, 0)]));
	let total = builds.reduce((sum, build) => sum + sizes.get(build.version), reserveBytes);
	for (const build of [...builds].reverse()) {
		if (pinned.has(build.version)) continue;
		const superseded = newestComplete && newestComplete.savedAt > build.savedAt;
		const expired = build.complete === false && now - build.savedAt > PARTIAL_BUILD_TTL;
		if (!superseded && !expired && total <= MAX_TOTAL_BYTES) continue;
		await caches.delete(`${PREFIX}${build.version}`);
		await meta.delete(`${META_ROOT}manifest/${build.version}`);
		total -= sizes.get(build.version);
	}
	// Partial builds have metadata too. Never delete a known preparation merely
	// because it has not finished, or an old page has not reported its version yet.
	const known = new Set((await listBuilds()).map((build) => `${PREFIX}${build.version}`));
	for (const name of await caches.keys()) {
		if (name.startsWith(PREFIX) && VERSION_PATTERN.test(name.slice(PREFIX.length)) &&
			!pinned.has(name.slice(PREFIX.length)) && !known.has(name)) await caches.delete(name);
	}
	if (total > MAX_TOTAL_BYTES) throw new Error("Active GoTab builds fill the asset cache budget");
}

const manifestKey = (version) => `${META_ROOT}manifest/${version}`;
async function readBuild(version) {
	try {
		const entry = await (await (await caches.open(META_CACHE)).match(manifestKey(version)))?.json();
		return isManifest(entry) ? entry : null;
	} catch { return null; }
}
async function writeBuild(build) {
	await (await caches.open(META_CACHE)).put(manifestKey(build.version),
		new Response(JSON.stringify(build), { headers: { "content-type": "application/json" } }));
}

// Persist the bounded manifest before creating its cache. A partial build is
// usable for individual verified assets, but is not marked fully offline-ready.
async function registerBuild(build) {
	if (!isManifest({ ...build, savedAt: Date.now() })) throw new Error("Invalid GoTab build manifest");
	const requiredBytes = build.assets.reduce((sum, asset) => sum + asset.size, 0);
	if (requiredBytes > MAX_BUILD_BYTES) throw new Error("GoTab build exceeds the asset cache budget");
	const existing = await readBuild(build.version);
	if (existing) {
		if (JSON.stringify(existing.assets) !== JSON.stringify(build.assets)) throw new Error("Conflicting GoTab build manifest");
		return existing;
	}
	await pruneCaches(requiredBytes, build.version);
	const entry = { ...build, savedAt: Date.now(), complete: false, preparingUntil: 0 };
	await writeBuild(entry);
	await caches.open(`${PREFIX}${build.version}`);
	return entry;
}

function validContentType(response, type) {
	const mime = (response.headers.get("content-type") || "").split(";", 1)[0].trim().toLowerCase();
	if (type === "script") return /^(?:text|application)\/(?:javascript|ecmascript|x-javascript)$/.test(mime);
	if (type === "style") return mime === "text/css";
	return /^(?:font\/|application\/(?:font-|x-font-|vnd\.ms-fontobject|octet-stream))/.test(mime);
}

async function verifiedResponse(response, asset) {
	if (!response || response.status !== 200 || response.redirected || response.type === "opaque" || !response.body || !validContentType(response, asset.type) || Number(response.headers.get("content-length")) > MAX_ASSET_BYTES) {
		if (response?.body) void response.body.cancel().catch(() => undefined);
		return null;
	}
	const reader = response.body.getReader();
	let timeout;
	try {
		const chunks = [];
		let size = 0;
		await Promise.race([
			(async () => {
				while (true) {
					const chunk = await reader.read();
					if (chunk.done) break;
					size += chunk.value.byteLength;
					if (size > asset.size || size > MAX_ASSET_BYTES) throw new Error("GoTab asset exceeds its build size");
					chunks.push(chunk.value);
				}
			})(),
			new Promise((_, reject) => { timeout = setTimeout(() => reject(new Error("GoTab asset body read timed out")), FETCH_TIMEOUT); }),
		]);
		if (size !== asset.size) return null;
		const bytes = new Uint8Array(size);
		let offset = 0;
		for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
		const digest = await crypto.subtle.digest("SHA-256", bytes);
		const hex = Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
		if (hex !== asset.hash) return null;
		const headers = new Headers(response.headers);
		// Fetch exposes decompressed bytes; the stored response describes those bytes.
		headers.delete("content-encoding");
		headers.set("content-length", String(size));
		return new Response(bytes, { status: 200, headers });
	} finally {
		clearTimeout(timeout);
		// Do not await cancellation of a tee used for a foreground network response.
		void reader.cancel().catch(() => undefined);
	}
}

async function fetchAsset(url, asset) {
	const controller = new AbortController();
	const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT);
	try {
		const response = await fetch(url, { credentials: "omit", cache: "no-cache", redirect: "error", signal: controller.signal });
		return await verifiedResponse(response, asset);
	} finally { clearTimeout(timeout); }
}

// A separate per-asset lock lets a foreground import share a background fetch
// without queueing behind unrelated files. Locks also coordinate active/installing workers.
async function ensureAsset(build, asset) {
	const url = new URL(asset.path, self.location.origin).href;
	const key = `${build.version}:${url}`;
	if (!assetTransfers.has(key)) {
		const load = async () => {
			const cacheName = `${PREFIX}${build.version}`;
			if (await caches.has(cacheName)) {
				const cached = await (await caches.open(cacheName)).match(url);
				if (cached) return cached;
			}
			let response;
			for (const older of await listBuilds()) {
				if (older.version === build.version || !older.assets.some((item) => item.path === asset.path && item.hash === asset.hash && item.size === asset.size)) continue;
				const name = `${PREFIX}${older.version}`;
				if (await caches.has(name)) response = await (await caches.open(name)).match(url);
				if (response) break;
			}
			if (!response) response = await fetchAsset(url, asset);
			if (!response) throw new Error("GoTab asset content does not match the deployed build");
			const stored = response.clone();
			try {
				await withBuildLock(async () => {
					const entry = await readBuild(build.version);
					// An obsolete in-flight request must not recreate an evicted build.
					if (!entry) return;
					await (await caches.open(cacheName)).put(url, stored);
					if (entry.preparingUntil > 0) await writeBuild({ ...entry, preparingUntil: Date.now() + PREPARATION_LEASE });
				});
			} catch { /* Cache quota/storage failure must not discard a valid foreground response. */ }
			return response;
		};
		const transfer = (self.navigator?.locks ? self.navigator.locks.request(`${PREFIX}asset:${key}`, load) : load())
			.finally(() => assetTransfers.delete(key));
		assetTransfers.set(key, transfer);
	}
	return (await assetTransfers.get(key)).clone();
}

// This is only a scheduling hint. Never fetch missing files, populate a cache, or
// trust a build's "complete" flag; ordinary import preparation still runs later.
async function cachedImportHints(message) {
	if (typeof message.version !== "string" || !VERSION_PATTERN.test(message.version) || !Array.isArray(message.imports) ||
		message.imports.length > 32 || message.imports.some((entry) =>
			!entry || typeof entry.importer !== "string" || entry.importer.length > 4096 ||
			typeof entry.key !== "string" || !VERSION_PATTERN.test(entry.key))) throw new Error("Invalid cached import query");
	const deadline = Date.now() + 1800;
	let active = true;
	let timeout;
	const check = () => {
		if (!active || Date.now() >= deadline) throw new Error("Cached import query timed out");
	};
	const read = async (response, maximum) => {
		check();
		if (!response || response.status !== 200 || response.redirected || response.type === "opaque") throw new Error("Invalid cached response");
		const bytes = await readLimited(response, maximum, Math.max(1, deadline - Date.now()));
		check();
		return bytes;
	};
	const work = async () => {
		// Open only names that already exist, under the same lock as application
		// eviction. Build key indexes once, shared by every requested component.
		const snapshots = await withBuildLock(async () => {
			check();
			const names = new Set(await caches.keys());
			check();
			if (!names.has(META_CACHE) || !await caches.has(META_CACHE)) return [];
			const metadata = await caches.open(META_CACHE);
			const versions = [...new Set([message.version, ...[...names].filter((name) => name.startsWith(PREFIX) &&
				VERSION_PATTERN.test(name.slice(PREFIX.length))).map((name) => name.slice(PREFIX.length))])];
			// A hint may conservatively miss when metadata is unexpectedly large.
			if (versions.length > 32) return [];
			versions.sort((left, right) => Number(right === message.version) - Number(left === message.version));
			const result = [];
			for (const version of versions) {
				check();
				try {
					const build = JSON.parse(new TextDecoder().decode(await read(await metadata.match(manifestKey(version)), 2 * 1024 * 1024)));
					if (!isManifest(build) || build.version !== version) continue;
					const assets = new Map(build.assets.map((asset) => [new URL(asset.path, self.location.origin).href, asset]));
					if (assets.size !== build.assets.length) continue;
					const cache = await caches.has(`${PREFIX}${version}`) ? await caches.open(`${PREFIX}${version}`) : null;
					const keys = new Set(cache ? (await cache.keys()).map((key) => key.url) : []);
					check();
					result.push({ version, assets, cache, keys });
				} catch { check(); /* Invalid/unavailable caches are not a hit. */ }
			}
			return result;
		});
		check();
		const current = snapshots.find((snapshot) => snapshot.version === message.version);
		if (!current) throw new Error("Requested cached build is unavailable");
		const resource = (value, importer) => {
			if (typeof value !== "string") throw new Error("Invalid cached module URL");
			const url = new URL(value, importer);
			const asset = current.assets.get(url.href);
			if (url.origin !== self.location.origin || url.search || url.hash || url.username || url.password ||
				!asset || !isAssetPath(url.pathname) ||
				!(url.pathname.endsWith(".js") && asset.type === "script" || url.pathname.endsWith(".css") && asset.type === "style")) throw new Error("Unknown cached module resource");
			return { url: url.href, asset };
		};
		const responses = new Map();
		const responseFor = ({ url, asset }) => {
			if (!responses.has(url)) responses.set(url, (async () => {
				for (const snapshot of snapshots) {
					check();
					const candidate = snapshot.assets.get(url);
					if (!snapshot.keys.has(url) || !candidate || candidate.path !== asset.path ||
						candidate.hash !== asset.hash || candidate.size !== asset.size || candidate.type !== asset.type) continue;
					try {
						const response = await snapshot.cache.match(url);
						check();
						// These bodies were verified before being stored. Checking headers
						// avoids reading and hashing every potentially large JS dependency.
						if (response?.status === 200 && !response.redirected && response.type !== "opaque" &&
							validContentType(response, asset.type) && Number(response.headers.get("content-length")) === asset.size) return response;
					} catch { check(); }
				}
				return null;
			})());
			return responses.get(url);
		};
		const graphs = new Map();
		const graphFor = (importer) => {
			if (!graphs.has(importer)) graphs.set(importer, (async () => {
				const sidecar = resource(importer.replace(/\.js$/, "-lazy-imports.js"), importer);
				const response = await responseFor(sidecar);
				const bytes = await read(response, Math.min(sidecar.asset.size, 1024 * 1024));
				if (bytes.byteLength !== sidecar.asset.size || await digest(bytes) !== sidecar.asset.hash) throw new Error("Invalid cached import graph");
				check();
				const source = new TextDecoder().decode(bytes);
				if (!source.startsWith("export default ")) throw new Error("Invalid cached import graph");
				const graph = JSON.parse(source.slice("export default ".length).replace(/;\s*$/, ""));
				if (!graph || !Array.isArray(graph.files) || graph.files.length > 4096 ||
					!Array.isArray(graph.available) || graph.available.length > 4096 ||
					!graph.entries || typeof graph.entries !== "object" || Array.isArray(graph.entries)) throw new Error("Invalid cached import graph");
				const files = graph.files.map((file) => resource(file, importer));
				const available = graph.available.map((file) => resource(file, importer));
				if (!available.some((file) => file.url === importer)) throw new Error("Invalid cached importer proof");
				const entries = Object.entries(graph.entries);
				if (entries.length > 4096 || entries.some(([key, indexes]) => !VERSION_PATTERN.test(key) ||
					!Array.isArray(indexes) || indexes.length > 4096 ||
					indexes.some((index) => !Number.isInteger(index) || index < 0 || index >= files.length))) throw new Error("Invalid cached import indexes");
				return { files, entries: graph.entries };
			})());
			return graphs.get(importer);
		};
		const cached = [];
		for (const entry of message.imports) {
			check();
			try {
				const owner = resource(entry.importer, HOME_URL);
				if (owner.url !== entry.importer || owner.asset.type !== "script" || !owner.url.endsWith(".js")) throw new Error("Invalid cached importer");
				const graph = await graphFor(owner.url);
				if (!Object.hasOwn(graph.entries, entry.key)) throw new Error("Unknown cached import");
				// The sidecar already includes transitive static dependencies. Its
				// available graph belongs to the executing importer and needs no read.
				let complete = true;
				for (const index of graph.entries[entry.key]) {
					if (!await responseFor(graph.files[index])) { complete = false; break; }
				}
				cached.push(complete);
			} catch { check(); cached.push(false); }
		}
		return { ok: true, version: message.version, cached };
	};
	try {
		return await Promise.race([work(), new Promise((_, reject) => {
			timeout = setTimeout(() => reject(new Error("Cached import query timed out")), 1800);
		})]);
	} finally {
		active = false;
		clearTimeout(timeout);
	}
}

function prepareBuild(build) {
	if (!buildPreparations.has(build.version)) {
		const populate = async () => {
			const complete = await withBuildLock(async () => {
				const entry = await registerBuild(build);
				const cache = await caches.open(`${PREFIX}${build.version}`);
				const stored = new Set((await cache.keys()).map((key) => key.url));
				if (build.assets.every((asset) => stored.has(new URL(asset.path, self.location.origin).href))) {
					if (entry.complete !== true || entry.preparingUntil) await writeBuild({ ...entry, complete: true, preparingUntil: 0 });
					await pruneCaches();
					return true;
				}
				await writeBuild({ ...entry, complete: false, preparingUntil: Date.now() + PREPARATION_LEASE });
				return false;
			});
			if (complete) return;
			let index = 0;
			let failed = false;
			try {
				const results = await Promise.allSettled(Array.from({ length: 4 }, async () => {
					while (!failed && index < build.assets.length) {
						try { await ensureAsset(build, build.assets[index++]); }
						catch (error) { failed = true; throw error; }
					}
				}));
				if (results.some((result) => result.status === "rejected")) throw new Error("GoTab asset cache installation was incomplete");
			} finally {
				await withBuildLock(async () => {
					const entry = await readBuild(build.version);
					if (!entry) return;
					const cache = await caches.open(`${PREFIX}${build.version}`);
					const stored = new Set((await cache.keys()).map((key) => key.url));
					const complete = build.assets.every((asset) => stored.has(new URL(asset.path, self.location.origin).href));
					await writeBuild({ ...entry, complete, preparingUntil: 0 });
					await pruneCaches();
					if (!complete) throw new Error("GoTab asset cache installation was incomplete");
				});
			}
		};
		const preparation = (self.navigator?.locks ? self.navigator.locks.request(`${PREFIX}prepare:${build.version}`, populate) : populate())
			.finally(() => buildPreparations.delete(build.version));
		buildPreparations.set(build.version, preparation);
	}
	return buildPreparations.get(build.version);
}

self.addEventListener("install", (event) => event.waitUntil((async () => {
	// Installing the cache handler must not require downloading every optional panel.
	await withBuildLock(() => registerBuild(BUILD));
	await self.skipWaiting();
})()));
self.addEventListener("activate", (event) => {
	event.waitUntil((async () => {
		await self.clients.claim();
		for (const client of await self.clients.matchAll({ type: "window" })) client.postMessage({ type: "gotab-assets:request-version" });
		await Promise.allSettled([checkHomePage(), prepareBuild(BUILD)]);
	})());
});

async function readClient(id) {
	try { return await (await (await caches.open(META_CACHE)).match(`${META_ROOT}client/${encodeURIComponent(id)}`)).json(); }
	catch { return {}; }
}

async function writeClient(id, entry) {
	if (!id) return;
	await (await caches.open(META_CACHE)).put(`${META_ROOT}client/${encodeURIComponent(id)}`, new Response(JSON.stringify({ ...entry, savedAt: Date.now() })));
}

const refreshKey = (token) => `${META_ROOT}refresh-token/${token}`;
const legacyRefreshKey = (url) => `${META_ROOT}refresh-page/${encodeURIComponent(url)}`;

async function refreshTarget(url) {
	const detected = await readDetectedPage(url);
	if (detected) return detected;
	const page = await (await caches.open(PAGE_CACHE)).match(url);
	const htmlRevision = await cachedHTMLRevision(page);
	return htmlRevision ? {
		version: page.headers.get(HTML_VERSION), htmlRevision,
		configRevision: page.headers.get(CONFIG_REVISION), configURL: page.headers.get(CONFIG_URL),
		checkSequence: Number(page.headers.get(HTML_CHECK_SEQUENCE)) || 0,
	} : null;
}

async function pruneRefreshTokens(cache) {
	for (const key of await cache.keys()) {
		if (!["refresh/", "refresh-token/", "refresh-page/"].some((prefix) => key.url.startsWith(`${META_ROOT}${prefix}`))) continue;
		try {
			const entry = await (await cache.match(key)).json();
			if (Number.isFinite(entry.savedAt) && Date.now() - entry.savedAt < REFRESH_TTL) continue;
		} catch { /* Remove invalid metadata with expired requests. */ }
		await cache.delete(key);
	}
}

const detectedPageKey = (url) => `${META_ROOT}detected/${encodeURIComponent(url)}`;

async function readDetectedRecord(url) {
	try {
		const response = await (await caches.open(META_CACHE)).match(detectedPageKey(url));
		const detected = response ? await response.json() : null;
		// Other workers can replace or clear this record. Memory is only a fallback
		// when storage is unavailable, never a reason to ignore their newer state.
		if (detected) detectedPages.set(url, detected);
		else detectedPages.delete(url);
		return detected;
	} catch { return detectedPages.get(url) || null; }
}

async function rememberDetectedPage(url, detected) {
	return withBuildLock(async () => {
		const current = await readDetectedRecord(url);
		let committed;
		try { committed = await (await caches.open(PAGE_CACHE)).match(url); } catch { /* A live notice can survive revoked storage. */ }
		if (Number(current?.checkSequence) > detected.checkSequence ||
			Number(committed?.headers.get(HTML_CHECK_SEQUENCE)) >= detected.checkSequence) return false;
		detectedPages.set(url, detected);
		try {
			await (await caches.open(META_CACHE)).put(detectedPageKey(url), new Response(JSON.stringify(detected)));
		} catch { /* Storage restrictions must not suppress a live update notice. */ }
		return true;
	});
}

// Call under the shared metadata lock. A completed check only owns its marker;
// unconditional clearing is reserved for revoked/evicted share pages.
async function clearDetectedPage(url, checkSequence) {
	if (checkSequence !== undefined) {
		const current = await readDetectedRecord(url);
		if (current?.checkSequence !== undefined && current.checkSequence !== checkSequence) return;
	}
	detectedPages.delete(url);
	try { await (await caches.open(META_CACHE)).delete(detectedPageKey(url)); }
	catch { /* A stale marker is also compared with the committed page below. */ }
}

async function readDetectedPage(url) {
	const detected = await readDetectedRecord(url);
	try {
		if (!detected || detected.htmlRevisionFormat !== DOCUMENT_REVISION_FORMAT ||
			!VERSION_PATTERN.test(detected.version) || !DIGEST_PATTERN.test(detected.htmlRevision) ||
			!DIGEST_PATTERN.test(detected.revision) || !configurationURL(detected.configURL) ||
			(detected.configRevision !== undefined && !DIGEST_PATTERN.test(detected.configRevision)) ||
			(detected.checkSequence !== undefined && (!Number.isSafeInteger(detected.checkSequence) || detected.checkSequence <= 0))) return null;
		const committed = await (await caches.open(PAGE_CACHE)).match(url);
		if (detected.checkSequence !== undefined && Number(committed?.headers.get(HTML_CHECK_SEQUENCE)) >= detected.checkSequence) return null;
		if (committed?.headers.get(HTML_REVISION_FORMAT) === DOCUMENT_REVISION_FORMAT &&
			committed.headers.get(HTML_CONTENT_REVISION) === detected.htmlRevision &&
			(!detected.configRevision || committed.headers.get(CONFIG_REVISION) === detected.configRevision)) return null;
		return detected;
	} catch { return detected || null; }
}

async function reportPage(client) {
	const url = pageURL(client.url);
	if (!url) return;
	const page = await readDetectedPage(url) || await (await caches.open(PAGE_CACHE)).match(url);
	if (!page) return;
	const served = await readClient(client.id);
	const pending = !(page instanceof Response);
	const htmlRevision = pending ? page.htmlRevision : await cachedHTMLRevision(page);
	if (!htmlRevision) return;
	const configRevision = pending ? page.configRevision : page.headers.get(CONFIG_REVISION);
	const revision = pending ? page.revision : page.headers.get(HTML_REVISION_FORMAT) === DOCUMENT_REVISION_FORMAT
		? page.headers.get(HTML_REVISION) : await combinedPageRevision(htmlRevision, configRevision);
	const servedDocumentRevision = served.htmlRevisionFormat === DOCUMENT_REVISION_FORMAT;
	client.postMessage({
		type: pending ? "gotab-pages:detected" : "gotab-pages:ready",
		version: pending ? page.version : page.headers.get(HTML_VERSION),
		revision, htmlRevision, htmlRevisionFormat: DOCUMENT_REVISION_FORMAT, configRevision,
		configURL: pending ? page.configURL : page.headers.get(CONFIG_URL),
		entryURL: pending ? page.entryURL : page.headers.get(HTML_ENTRY_URL),
		servedRevision: servedDocumentRevision ? served.pageRevision : undefined,
		servedHtmlRevision: servedDocumentRevision ? served.htmlContentRevision : undefined,
		servedConfigRevision: served.configRevision, servedConfigURL: served.configURL,
		pageKind: pageKind(url), pageURL: url,
	});
}

async function broadcastPage(url) {
	for (const client of await self.clients.matchAll({ type: "window" })) {
		if (pageURL(client.url) === url) await reportPage(client);
	}
}

self.addEventListener("message", (event) => {
	if (event.data?.type === "gotab-pages:first-paint-ready" && event.source?.id) {
		if (pageURL(event.source.url)) reloadPaintFor(event.source.id).finish();
		return;
	}
	if (!["gotab-assets:client-version", "gotab-assets:cached-imports", "gotab-pages:check", "gotab-pages:refresh", "gotab-pages:share-public", "gotab-pages:share-revoke"].includes(event.data?.type) || !event.source?.id) return;
	let source;
	try { source = new URL(event.source.url); } catch { return; }
	if (source.origin !== self.location.origin || !source.pathname.startsWith(BUILD.scope)) return;
	event.waitUntil((async () => {
		if (event.data.type === "gotab-assets:cached-imports") {
			if (!event.ports?.[0]) return;
			event.ports?.[0]?.postMessage(await cachedImportHints(event.data));
			return;
		}
		const url = pageURL(source.href);
		if (event.data.type === "gotab-pages:refresh") {
			if (!url) { event.ports?.[0]?.postMessage({ ok: true }); return; }
			const token = event.data.token;
			if (token !== undefined && !REFRESH_TOKEN.test(token)) return;
			// Only short metadata work holds this lock, never resource downloads.
			await withBuildLock(async () => {
				const cache = await caches.open(META_CACHE);
				await pruneRefreshTokens(cache);
				const entry = { url, savedAt: Date.now(), target: await refreshTarget(url) };
				if (token) await cache.put(refreshKey(token), new Response(JSON.stringify(entry)));
				else {
					// Pages from before the token protocol still call location.reload().
					await cache.put(`${META_ROOT}refresh/${encodeURIComponent(event.source.id)}`, new Response(JSON.stringify(entry)));
					await cache.put(legacyRefreshKey(url), new Response(JSON.stringify({ ...entry, clientId: event.source.id })));
				}
			});
			event.ports?.[0]?.postMessage({ ok: true, token });
			return;
		}
		if (event.data.type.startsWith("gotab-pages:share-")) {
			if (!url || pageKind(url) !== "share" || event.data.path !== source.pathname) return;
			if (event.data.type === "gotab-pages:share-revoke") {
				await withBuildLock(async () => {
					await (await caches.open(META_CACHE)).delete(publicShareKey(url));
					await (await caches.open(PAGE_CACHE)).delete(url);
					await clearDetectedPage(url);
				});
			} else {
				// Only the application's fresh successful public payload authorizes a
				// share shell. Its API remains outside the worker's fetch handler.
				await (await caches.open(META_CACHE)).put(publicShareKey(url), new Response(JSON.stringify({ savedAt: Date.now() })));
				await checkPage(url);
			}
			return;
		}
		if (event.data.type === "gotab-pages:check") {
			if (url) {
				// A cached navigation can discover an update before its page listener
				// exists. Replay it without waiting for that update's resource download.
				await reportPage(event.source);
				await checkPage(url, event.data.reuseRecentConfig === true);
				await reportPage(event.source);
			}
			return;
		}
		if (!VERSION_PATTERN.test(event.data.version)) return;
		// Navigation already pinned the served HTML. The build lock may still be
		// preparing its replacement, so do not put the pending notice behind it.
		await reportPage(event.source);
		await withBuildLock(async () => {
			const entry = await readClient(event.source.id);
			const reportedURL = typeof event.data.configURL === "string" ? configurationURL(event.data.configURL) : null;
			await writeClient(event.source.id, { ...entry, version: event.data.version, ...(!entry.configURL && reportedURL ? { configURL: reportedURL } : {}) });
			await pruneCaches();
		});
		await reportPage(event.source);
	})().catch(() => { event.ports?.[0]?.postMessage({ ok: false }); }));
});

async function readLimited(response, maximum, timeoutMs = FETCH_TIMEOUT) {
	if (!response.body || Number(response.headers.get("content-length")) > maximum) throw new Error("GoTab update response is too large");
	const reader = response.body.getReader();
	let timeout;
	try {
		return await Promise.race([(async () => {
			const chunks = []; let size = 0;
			while (true) {
				const { done, value } = await reader.read();
				if (done) break;
				size += value.byteLength;
				if (size > maximum) throw new Error("GoTab update response is too large");
				chunks.push(value);
			}
			const bytes = new Uint8Array(size); let offset = 0;
			for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
			return bytes;
		})(), new Promise((_, reject) => { timeout = setTimeout(() => reject(new Error("GoTab update body timed out")), timeoutMs); })]);
	} finally { clearTimeout(timeout); void reader.cancel().catch(() => undefined); }
}

function decodeHTML(value) {
	const entities = { amp: "&", quot: '"', apos: "'", lt: "<", gt: ">", nbsp: "\u00a0" };
	return value.replace(/&(#(?:x[\da-f]+|\d+)|amp|quot|apos|lt|gt|nbsp);/gi, (entity, name) => {
		name = name.toLowerCase();
		if (!name.startsWith("#")) return entities[name];
		const code = name.startsWith("#x") ? Number.parseInt(name.slice(2), 16) : Number(name.slice(1));
		return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : entity;
	});
}

function readDocumentIdentity(html) {
	// Skip comments and raw text bodies so injected JavaScript and CSS can't
	// introduce apparent GoTab tags. A Service Worker has no DOMParser.
	const tags = /<!--[\s\S]*?(?:-->|$)|<(script|style|title|textarea)(?=[\s/>])((?:"[^"]*"|'[^']*'|[^"'<>])*)>([\s\S]*?)<\/\1\s*>|<([a-z][\w:-]*)(?=[\s/>])((?:"[^"]*"|'[^']*'|[^"'<>])*)>/gi;
	const titles = [];
	const seo = { description: [], keywords: [] };
	const configurations = [];
	const entries = [];
	let version = null;
	for (const [, rawTag, rawAttributes, body, tag, attributes] of html.matchAll(tags)) {
		const kind = (rawTag || tag)?.toLowerCase();
		if (kind === "title" && rawTag) {
			titles.push(decodeHTML(body).replace(/\s+/g, " ").trim());
			continue;
		}
		if (kind !== "meta" && kind !== "script") continue;
		const attrs = new Map();
		for (const [, key, doubleQuoted, singleQuoted, unquoted] of (rawAttributes ?? attributes).matchAll(/([^\s/="'<>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g)) {
			const name = key.toLowerCase();
			if (!attrs.has(name)) attrs.set(name, decodeHTML(doubleQuoted ?? singleQuoted ?? unquoted ?? ""));
		}
		if (kind === "script") {
			const url = configurationURL(attrs.get("src"));
			if (url) configurations.push(url);
			if (attrs.get("type")?.toLowerCase() === "module") {
				const entry = applicationEntryURL(attrs.get("src"));
				if (entry) entries.push(entry);
			}
			continue;
		}
		const name = attrs.get("name")?.toLowerCase();
		const content = attrs.get("content");
		if (name === "gotab-asset-cache" && attrs.get("data-scope") === BUILD.scope) version = content;
		if (Object.hasOwn(seo, name) && content !== undefined) seo[name].push(content.replace(/\s+/g, " ").trim());
	}
	const configURL = configurations.length === 1 ? configurations[0] : null;
	const entryURL = entries.length === 1 ? entries[0] : null;
	return { version, configURL, entryURL, titles, seo };
}

async function inspectHTML(response) {
	if (!response || response.status !== 200 || response.redirected || response.type === "opaque" || !/^text\/html(?:;|$)/i.test(response.headers.get("content-type") || "")) return null;
	const bytes = await readLimited(response, 1024 * 1024);
	const identity = readDocumentIdentity(new TextDecoder().decode(bytes));
	const { version, configURL, entryURL } = identity;
	if (!VERSION_PATTERN.test(version)) return null;
	// Build identity covers the HTML template and compiled assets. The rendered
	// title/SEO and config reference can also change independently of a build.
	const revision = await digest(new TextEncoder().encode(JSON.stringify(identity)));
	const headers = new Headers(response.headers);
	headers.delete("content-encoding");
	headers.set("content-length", String(bytes.byteLength));
	headers.set(HTML_VERSION, version);
	headers.set(HTML_CONTENT_REVISION, revision);
	headers.set(HTML_REVISION_FORMAT, DOCUMENT_REVISION_FORMAT);
	if (entryURL) headers.set(HTML_ENTRY_URL, entryURL);
	else headers.delete(HTML_ENTRY_URL);
	return { version, revision, configURL, entryURL, response: new Response(bytes, { status: 200, headers }) };
}

async function cachedHTMLRevision(page) {
	if (!page) return null;
	if (page.headers.get(HTML_REVISION_FORMAT) === DOCUMENT_REVISION_FORMAT) return page.headers.get(HTML_CONTENT_REVISION);
	// Adopt an existing cached document without treating the old raw-HTML
	// checksum as a new release. The response body is left intact.
	try { return (await inspectHTML(page.clone()))?.revision ?? null; }
	catch { return null; }
}

function combinedPageRevision(htmlRevision, configRevision) {
	return digest(new TextEncoder().encode(`${htmlRevision}\n${configRevision}`));
}

async function inspectConfiguration(response, url) {
	if (!configurationURL(url) || !response || response.status !== 200 || response.redirected || response.type === "opaque" || !validContentType(response, "script")) return null;
	const bytes = await readLimited(response, MAX_CONFIG_BYTES);
	if (!bytes.byteLength) return null;
	const version = new URL(url).searchParams.get("v");
	// GoTab Server serves the current file even for an old ?v=. Never accept that
	// response as the historical configuration referenced by an older document.
	if (version !== null && crc32(bytes) !== Number(version)) return null;
	const revision = await digest(bytes);
	const headers = new Headers(response.headers);
	headers.delete("content-encoding");
	headers.set("content-length", String(bytes.byteLength));
	headers.set(CONFIG_REVISION, revision);
	headers.set(CONFIG_SAVED_AT, String(Date.now()));
	return { revision, size: bytes.byteLength, response: new Response(bytes, { status: 200, headers }) };
}

async function fetchUpdate(url) {
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT);
	try {
		const response = await fetch(url, { credentials: "omit", cache: "no-store", redirect: "error", signal: controller.signal });
		if (response.status !== 200) throw new Error("GoTab update is unavailable");
		return response;
	} finally { clearTimeout(timer); }
}

async function preparePage(next, url, checkSequence) {
	const config = await inspectConfiguration(await fetchUpdate(next.configURL), next.configURL);
	if (!config) throw new Error("GoTab configuration does not match its document");
	if (!new URL(next.configURL).searchParams.has("v")) {
		const confirmed = await inspectHTML(await fetchUpdate(url));
		if (!confirmed || confirmed.revision !== next.revision || confirmed.configURL !== next.configURL) throw new Error("GoTab document changed while preparing its configuration");
	}
	const revision = await combinedPageRevision(next.revision, config.revision);
	const committed = await withBuildLock(async () => {
		if (pageKind(url) === "share" && !(await isPublicShare(url))) return false;
		const cache = await caches.open(PAGE_CACHE);
		const previous = await cache.match(url);
		// A slow check in another worker must not roll back a later check's pair.
		if (checkSequence !== undefined && Number(previous?.headers.get(HTML_CHECK_SEQUENCE)) > checkSequence) return false;
		await storeConfiguration(config);
		const headers = new Headers(next.response.headers);
		headers.set(HTML_REVISION, revision);
		headers.set(CONFIG_REVISION, config.revision);
		headers.set(CONFIG_URL, next.configURL);
		headers.set(PAGE_SAVED_AT, String(Date.now()));
		if (checkSequence !== undefined) headers.set(HTML_CHECK_SEQUENCE, String(checkSequence));
		// Commit the matching HTML/config pair now. Missing assets load normally
		// after refresh; full offline readiness is tracked separately on the build.
		await cache.put(url, new Response(next.response.body, { status: 200, headers }));
		if (pageKind(url) === "share") {
			if (!(await isPublicShare(url))) await cache.delete(url);
			await pruneSharePages(url);
		}
		await clearDetectedPage(url, checkSequence);
		return true;
	});
	if (committed) await broadcastPage(url);
	return committed;
}

// Keep prefetching on the event lifetime while allowing another HTML check
// to detect a later deployment before this build's downloads finish.
async function preparePageAssets(next, url) {
	if (pageKind(url) === "share" && !(await isPublicShare(url))) return;
	let build = next.version === BUILD.version ? BUILD : await readBuild(next.version);
	if (!build) {
		const response = await fetchUpdate(new URL(`gotab-asset-manifest.json?v=${next.version}`, HOME_URL).href);
		if (!/^application\/json(?:;|$)/i.test(response.headers.get("content-type") || "")) throw new Error("GoTab manifest MIME type mismatch");
		build = JSON.parse(new TextDecoder().decode(await readLimited(response, 2 * 1024 * 1024)));
		if (build.version !== next.version || !isManifest({ ...build, savedAt: Date.now() })) throw new Error("GoTab manifest version mismatch");
	}
	await prepareBuild(build);
}

async function pruneSharePages(reservedURL) {
	const cache = await caches.open(PAGE_CACHE);
	const entries = await Promise.all((await cache.keys()).filter((key) => pageKind(key.url) === "share").map(async (key) => ({
		key, savedAt: Number((await cache.match(key)).headers.get(PAGE_SAVED_AT)) || 0,
		valid: await isPublicShare(key.url),
	})));
	entries.sort((a, b) => b.savedAt - a.savedAt);
	let kept = 0;
	for (const entry of entries) {
		if (entry.valid && (entry.key.url === reservedURL || kept < MAX_SHARE_PAGES)) { kept += 1; continue; }
		await cache.delete(entry.key);
		await (await caches.open(META_CACHE)).delete(publicShareKey(entry.key.url));
		await clearDetectedPage(entry.key.url);
	}
}

function checkPage(url = HOME_URL, reuseRecentConfig = false) {
	if (!checkingPages.has(url)) {
		checkingPages.set(url, (async () => {
			if (pageKind(url) === "share" && !(await isPublicShare(url))) return;
			const checkSequence = await withBuildLock(async () => {
				const cache = await caches.open(META_CACHE);
				const key = `${META_ROOT}check/${encodeURIComponent(url)}`;
				let previous = 0;
				try { previous = Number(await (await cache.match(key))?.text()) || 0; } catch { /* Start a new counter. */ }
				const sequence = previous + 1;
				await cache.put(key, new Response(String(sequence)));
				return sequence;
			});
			const next = await inspectHTML(await fetchUpdate(url));
			if (!next?.configURL) return;
			const previous = await (await caches.open(PAGE_CACHE)).match(url);
			if (Number(previous?.headers.get(HTML_CHECK_SEQUENCE)) > checkSequence) return;
			const changed = await cachedHTMLRevision(previous) !== next.revision;
			if (reuseRecentConfig && !changed && Date.now() - Number(previous?.headers.get(PAGE_SAVED_AT)) < CONFIG_CHECK_INTERVAL) return;
			if (changed) {
				const detected = {
					version: next.version, revision: next.revision, htmlRevision: next.revision,
					htmlRevisionFormat: DOCUMENT_REVISION_FORMAT, configURL: next.configURL, entryURL: next.entryURL, checkSequence,
				};
				const remembered = await rememberDetectedPage(url, detected);
				// Notify before fetching config or waiting for any build asset.
				if (remembered) await broadcastPage(url);
			}
			if (await preparePage(next, url, checkSequence)) return { assets: preparePageAssets(next, url) };
		})().finally(() => { checkingPages.delete(url); }));
	}
	return checkingPages.get(url).then((result) => result?.assets);
}
const checkHomePage = () => checkPage(HOME_URL);

async function consumeRefresh(event, url) {
	return withBuildLock(async () => {
		const cache = await caches.open(META_CACHE);
		const token = new URL(event.request.url).searchParams.get(REFRESH_QUERY);
		const keys = REFRESH_TOKEN.test(token || "") ? [refreshKey(token)] :
			[event.clientId, event.replacesClientId].filter(Boolean).map((id) => `${META_ROOT}refresh/${encodeURIComponent(id)}`);
		// Older documents cannot carry a token. On browsers that omit navigation
		// client IDs, a revalidation of this exact page can consume their intent.
		if (!token && await isReloadNavigation(event.request, event, url)) keys.push(legacyRefreshKey(url));
		for (const key of keys) {
			const response = await cache.match(key);
			if (!response) continue;
			try {
				const entry = await response.json();
				if (entry.url !== url) continue;
				await cache.delete(key);
				if (!Number.isFinite(entry.savedAt) || Date.now() - entry.savedAt >= REFRESH_TTL) continue;
				if (!token) {
					await cache.delete(legacyRefreshKey(url));
					if (entry.clientId) await cache.delete(`${META_ROOT}refresh/${encodeURIComponent(entry.clientId)}`);
				}
				return entry;
			} catch { await cache.delete(key); }
		}
		return null;
	});
}

async function isReloadNavigation(request, event, url) {
	// Cache modes alone also occur on ordinary navigation with cache disabled.
	// Prefer the explicit Fetch signal, including an authoritative false value.
	if (typeof request.isReloadNavigation === "boolean") return request.isReloadNavigation;
	if (request.isHistoryNavigation || !["no-cache", "reload"].includes(request.cache)) return false;
	// Legacy navigation often has neither client ID. Revalidation is sufficient
	// only when serveNavigation also finds a pending update for this exact path.
	for (const id of [event.replacesClientId, event.clientId].filter(Boolean)) {
		if ((await readClient(id)).pageURL === url) return true;
	}
	return !event.replacesClientId && !event.clientId;
}

async function serveCachedNavigation(url, kind, event, target) {
	try {
		const response = await withBuildLock(async () => {
			if (kind !== "home" && !(await isPublicShare(url))) return null;
			const cached = await (await caches.open(PAGE_CACHE)).match(url);
			if (!cached || !event.resultingClientId) return null;
			const configRevision = cached.headers.get(CONFIG_REVISION);
			if (!(await cachedConfiguration(configRevision))) return null;
			const htmlRevision = await cachedHTMLRevision(cached);
			if (!htmlRevision) return null;
			if (target && (htmlRevision !== target.htmlRevision ||
				(target.configRevision && configRevision !== target.configRevision))) {
				// Check order cannot establish deployment order (a CDN can return an
				// older document). Only this confirmed pair may satisfy the refresh.
				return null;
			}
			// The pair stays protected until the resulting client's pin is durable.
			// Otherwise another worker can switch/prune it between read and pin.
			const pageRevision = cached.headers.get(HTML_REVISION_FORMAT) === DOCUMENT_REVISION_FORMAT
				? cached.headers.get(HTML_REVISION) : await combinedPageRevision(htmlRevision, configRevision);
			await writeClient(event.resultingClientId, {
				version: cached.headers.get(HTML_VERSION), pageRevision,
				htmlContentRevision: htmlRevision, htmlRevisionFormat: DOCUMENT_REVISION_FORMAT, configRevision,
				configURL: cached.headers.get(CONFIG_URL), pageKind: kind, pageURL: url,
			});
			return cached;
		});
		if (response) event.waitUntil(checkPage(url).catch(() => undefined));
		return response;
	} catch { return null; }
}

async function serveNavigation(request, event) {
	const url = pageURL(request.url);
	const kind = pageKind(url);
	let refresh = false;
	let target;
	try {
		const intent = await consumeRefresh(event, url);
		target = intent?.target;
		refresh = Boolean(intent);
		if (!refresh && await isReloadNavigation(request, event, url)) {
			target = await readDetectedPage(url);
			refresh = Boolean(target);
		}
	} catch { /* Storage may be unavailable. */ }
	// Unregistered/expired markers still bypass old HTML, but cannot select a
	// cached target or gain authorization to a private share page.
	if (new URL(request.url).searchParams.has(REFRESH_QUERY)) refresh = true;
	if (!refresh || target) {
		const cached = await serveCachedNavigation(url, kind, event, refresh ? target : undefined);
		if (cached) return cached;
	}
	let failedResponse;
	let networkError;
	try {
		const network = await serveNetworkNavigation(request, event, kind, refresh);
		if (!refresh || network.status < 500) {
			event.waitUntil(checkPage(url).catch(() => undefined));
			return network;
		}
		failedResponse = network;
	} catch (error) { networkError = error; }
	// A deliberate update during an outage can retain the cached HTML/config pair.
	// Do not hide permission errors, removals or redirects behind an old page.
	if (refresh) {
		const cached = await serveCachedNavigation(url, kind, event);
		if (cached) return cached;
	}
	if (failedResponse) return failedResponse;
	throw networkError;
}

async function serveNetworkNavigation(request, event, kind, refresh = false) {
	const cleanURL = refresh ? pageURL(request.url) : navigationURL(request.url).href;
	const response = request.url !== cleanURL
		? await fetch(cleanURL, { headers: request.headers, credentials: request.credentials, cache: "no-store", redirect: request.redirect, referrer: request.referrer, referrerPolicy: request.referrerPolicy })
		: await fetch(refresh ? new Request(request, { cache: "no-store" }) : request);
	if (event.resultingClientId) {
		try {
			const document = await inspectHTML(response.clone());
			if (document?.configURL) {
				const url = pageURL(request.url);
				await withBuildLock(async () => {
					const record = {
						version: document.version, htmlContentRevision: document.revision, htmlRevisionFormat: DOCUMENT_REVISION_FORMAT,
						configURL: document.configURL, pageKind: kind, pageURL: url, refreshConfiguration: refresh,
					};
					const page = await (await caches.open(PAGE_CACHE)).match(url);
					// A user-confirmed refresh must not pair fresh unversioned HTML with
					// the old config even when its build/script URL happens to be unchanged.
					if (!refresh && page?.headers.get(HTML_VERSION) === document.version && page.headers.get(CONFIG_URL) === document.configURL &&
						await cachedHTMLRevision(page) === document.revision && await cachedConfiguration(page.headers.get(CONFIG_REVISION))) {
						record.configRevision = page.headers.get(CONFIG_REVISION);
						record.pageRevision = await combinedPageRevision(document.revision, record.configRevision);
					}
					await writeClient(event.resultingClientId, record);
				});
			}
		} catch { /* Network navigation and its initial data flow remain usable. */ }
	}
	return response;
}

async function serveConfiguration(request, event) {
	const url = configurationURL(request.url);
	let entry;
	try {
		entry = await readClient(event.clientId);
		if (entry.configURL === url && DIGEST_PATTERN.test(entry.configRevision)) {
			const cached = await cachedConfiguration(entry.configRevision);
			if (cached) { event.waitUntil(checkPage(entry.pageURL || HOME_URL).catch(() => undefined)); return cached; }
		}
	} catch { /* Revoked storage falls through to the ordinary network request. */ }
	const response = await fetch(entry?.refreshConfiguration ? new Request(request, { cache: "no-store" }) : request);
	let inspected;
	if (entry?.configURL === url && DIGEST_PATTERN.test(entry.configRevision)) {
		try { inspected = await inspectConfiguration(response.clone(), url); } catch { /* A missing pin must never switch versions. */ }
		if (!inspected || inspected.revision !== entry.configRevision) return Response.error();
	}
	// Only an intercepted public document may seed a configuration pin. Requests
	// from arbitrary clients/URLs cannot populate this cache or borrow a newer pin.
	if (entry?.configURL === url && ["home", "share"].includes(entry.pageKind)) {
		event.waitUntil((async () => {
			const config = inspected || await inspectConfiguration(response.clone(), url);
			if (!config) return;
			// If an old pinned entry was evicted, accepting today's different config
			// would silently switch this document's version. Do not record that pair.
			if (entry.configRevision && entry.configRevision !== config.revision) return;
			await withBuildLock(async () => {
				await storeConfiguration(config);
				const current = await readClient(event.clientId);
				if (current.configURL !== url || current.version !== entry.version) return;
				const pageRevision = await combinedPageRevision(entry.htmlContentRevision, config.revision);
				await writeClient(event.clientId, { ...current, configRevision: config.revision, pageRevision, refreshConfiguration: false });
			});
			const client = await self.clients.get(event.clientId);
			if (client) await reportPage(client);
		})().catch(() => undefined));
	}
	return response;
}

async function matchAsset(url) {
	const current = currentAssets.get(url);
	if (current) return { asset: current, build: BUILD };
	// Another worker can register a build at any time. Do not retain a stale
	// in-memory manifest list across update events or newly controlled documents.
	for (const build of await listBuilds()) {
		const asset = build.assets.find((item) => new URL(item.path, self.location.origin).href === url);
		if (asset) return { asset, build };
	}
	return null;
}

async function serveAsset(request, event) {
	let entry;
	try { entry = await matchAsset(request.url); }
	catch { /* Storage access can be revoked at any time. */ }
	if (!entry) return fetch(request);
	try { return await ensureAsset(entry.build, entry.asset); }
	catch {
		// Cache/quota failures must not make an otherwise available module unusable.
		// The browser's HTTP cache can still satisfy this ordinary request.
		return fetch(request);
	}
}

self.addEventListener("fetch", (event) => {
	const request = event.request;
	if (request.method !== "GET" || request.headers.has("range")) return;
	if (request.url === RELOAD_PAINT_URL && request.destination === "script" && event.clientId) {
		// This local response only releases the browser's native first-paint
		// blocker. It never goes to the server or contains a previous page.
		event.respondWith(reloadPaintFor(event.clientId).ready.then(() => new Response("", {
			headers: { "Content-Type": "text/javascript", "Cache-Control": "no-store" },
		})));
		return;
	}
	const navigationURL = new URL(request.url);
	if (request.mode === "navigate") {
		const kind = pageKind(navigationURL.href);
		if (kind === "home" || kind === "share") event.respondWith(serveNavigation(request, event));
		return;
	}
	const url = new URL(request.url);
	if (configurationURL(url.href)) { event.respondWith(serveConfiguration(request, event)); return; }
	if (url.origin !== self.location.origin || !isAssetPath(url.pathname)) return;
	// Unknown URLs pass through untouched and cannot populate the cache, including
	// new builds seen by an old worker, query variants and server fallback pages.
	event.respondWith(serveAsset(request, event));
});
